@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/spline-sans-mono";

/* Light (the faithful mode): a warm cream page (#f3f1e0) with near-black text (#212121),
   camel/tan bands (#ad9069) as `secondary`, and a hard signal yellow (#ffcc00) for every buy
   button, active tab and star. The always-dark sections wrap themselves in .dark. */
:root {
  --background: #f3f1e0;
  --foreground: #212121;
  --card: #f8f7ec;
  --card-foreground: #212121;
  --popover: #f8f7ec;
  --popover-foreground: #212121;
  --primary: #ffcc00;
  --primary-foreground: #212121;
  --secondary: #ad9069;
  --secondary-foreground: #212121;
  --muted: #e4e1cc;
  --muted-foreground: #5f5d55;
  --accent: #e9e6d2;
  --accent-foreground: #212121;
  --destructive: #c8402c;
  --destructive-foreground: #f3f1e0;
  --border: rgb(33 33 33 / 15%);
  --input: rgb(33 33 33 / 30%);
  --ring: #ffcc00;
  --highlight: #ffcc00;
  --highlight-foreground: #212121;
  --glow: #ad9069;
  --chart-1: #ffcc00;
  --chart-2: #ad9069;
  --chart-3: #212121;
  --chart-4: #808080;
  --chart-5: #6f5a3d;
  --sidebar: #f8f7ec;
  --sidebar-foreground: #212121;
  --sidebar-primary: #ffcc00;
  --sidebar-primary-foreground: #212121;
  --sidebar-accent: #e9e6d2;
  --sidebar-accent-foreground: #212121;
  --sidebar-border: rgb(33 33 33 / 15%);
  --sidebar-ring: #ffcc00;

  /* Universal Sans Display -> Hanken Grotesk; Aeonik Fono (semi-mono labels) -> Spline Sans Mono */
  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Spline Sans Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.3125rem;
  --page-width: 90rem;
  --page-gutter: 1.3125rem;
  --section-y: 4.5rem;
}

/* Desktop: 40px gutters and ~120px section padding, as measured at 1440. */
@media (min-width: 64rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 7.5rem;
  }
}

/* Dark: the original's near-black (#212121) with cream text; glass surfaces are cream at
   15-20%, inactive index boxes mid-grey, and the tan dimmed for whole-page dark use. */
.dark {
  --background: #212121;
  --foreground: #f3f1e0;
  --card: #2b2b2a;
  --card-foreground: #f3f1e0;
  --popover: #2b2b2a;
  --popover-foreground: #f3f1e0;
  --primary: #ffcc00;
  --primary-foreground: #212121;
  --secondary: #6f5d45;
  --secondary-foreground: #f3f1e0;
  --muted: #3e3d39;
  --muted-foreground: #a8a69b;
  --accent: rgb(244 242 226 / 15%);
  --accent-foreground: #f3f1e0;
  --destructive: #e0614c;
  --destructive-foreground: #212121;
  --border: rgb(244 242 226 / 20%);
  --input: rgb(244 242 226 / 20%);
  --ring: #ffcc00;
  --highlight: #ffcc00;
  --highlight-foreground: #212121;
  --glow: #ad9069;
  --chart-1: #ffcc00;
  --chart-2: #ad9069;
  --chart-3: #f3f1e0;
  --chart-4: #808080;
  --chart-5: #d8c29f;
  --sidebar: #2b2b2a;
  --sidebar-foreground: #f3f1e0;
  --sidebar-primary: #ffcc00;
  --sidebar-primary-foreground: #212121;
  --sidebar-accent: rgb(244 242 226 / 15%);
  --sidebar-accent-foreground: #f3f1e0;
  --sidebar-border: rgb(244 242 226 / 20%);
  --sidebar-ring: #ffcc00;
}
